  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Approves a pending IPO application if the related customer is still eligible for IPO.
   * When approval succeeds, the application status becomes APPROVAL and two informational emails are created:
   * one for the customer and one for the company.
   * Algorithm:
   * 1. Check that the current application status is PENDING.
   * 2. Check that the related customer exists and customer.isEligibleForIPO() is true.
   * 3. If either check fails, return false.
   * 4. Set status to APPROVAL.
   * 5. Create two informational Email objects, one addressed to the customer and one addressed to the company.
   * 6. Store both emails in emails.
   * 7. Return true.
   * Related Features:
   * - status
   * - customer
   * - company
   * - share
   * - amountOfMoney
   * - emails
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input:
   * - No explicit parameters.
   * - Uses the current Application instance state.
   * Output:
   * - boolean
   * - true if the application was approved successfully and informational emails were created.
   * - false otherwise.
   * Pre-condition:
   * - The application must be in PENDING status.
   * - The related customer must still be eligible for IPO.
   * - customer, company, and allowance must be present in the application.
   * Post-condition:
   * - On success, status is APPROVAL.
   * - On success, two informational emails are stored in emails.
   * - On failure, the application state is unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING)
    {
      return false;
    }
    Customer customer = getCustomer();
    Company company = getCompany();
    if (customer == null || company == null || getAllowance() == null || !customer.isEligibleForIPO())
    {
      return false;
    }

    setStatus(ApplicationStatus.APPROVAL);

    if (emails == null)
    {
      emails = new BasicEList<Email>();
    }
    else
    {
      emails.clear();
    }

    Email customerEmail = new Email();
    customerEmail.setReceiver(customer.getEmail());
    customerEmail.createEmailContent(company, share, customer, amountOfMoney);
    emails.add(customerEmail);

    Email companyEmail = new Email();
    companyEmail.setReceiver(company.getEmail());
    companyEmail.createEmailContent(company, share, customer, amountOfMoney);
    emails.add(companyEmail);

    return true;
    
  }

